package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen0Test {

    // Concrete implementation of ValuedEnum for testing
    private enum TestEnum implements ValuedEnum {
        INSTANCE_1("INSTANCE_1", 1),
        INSTANCE_2("INSTANCE_2", 2);

        private final String name;
        private final int iValue;

        TestEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    // Another enum to test ClassCastException
    private enum DifferentEnum implements ValuedEnum {
        OTHER("OTHER", 1);

        private final String name;
        private final int iValue;

        DifferentEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @Test
    public void testCompareTo_SameInstance() {
        TestEnum instance = TestEnum.INSTANCE_1;
        // if (other == this) return -1;
        assertEquals(-1, instance.compareTo(instance));
    }

    @Test
    public void testCompareTo_SameClass_Less() {
        TestEnum first = TestEnum.INSTANCE_1;
        TestEnum second = TestEnum.INSTANCE_2;
        // 1 - 2 = -1
        assertEquals(-1, first.compareTo(second));
    }

    @Test
    public void testCompareTo_SameClass_Greater() {
        TestEnum first = TestEnum.INSTANCE_2;
        TestEnum second = TestEnum.INSTANCE_1;
        // 2 - 1 = 1
        assertEquals(1, first.compareTo(second));
    }

    @Test
    public void testCompareTo_SameClass_Equal() {
        // Since same instance is handled by 'other == this', 
        // we test equality where values are same but objects are different if possible.
        // In Enums, constants are unique, but we test the logic flow.
        TestEnum first = TestEnum.INSTANCE_1;
        // Manually simulating a scenario where values might be equal if it weren't an enum
        // but for standard enum usage:
        assertEquals(0, first.compareTo(TestEnum.INSTANCE_1)); 
        // Note: the code returns -1 for same instance, so we check logic for different objects with same value
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_DifferentClass() {
        TestEnum first = TestEnum.INSTANCE_1;
        DifferentEnum second = DifferentEnum.OTHER;
        // Should throw ClassCastException because classes are different
        first.compareTo(second);
    }

    @Test
    public void testCompareTo_Null() {
        TestEnum first = TestEnum.INSTANCE_1;
        try {
            first.compareTo(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected behavior when accessing other.getClass()
        }
    }
}
